      const names=r.right?'A4–C5–E5':'A3–C4–E4',digits=r.right?'1–3–5':'5–3–1',hand=r.right?'Правая':'Левая',upper=r.right?'E5':'E4',root=r.right?'A4':'A3',third=r.right?'C5':'C4',starts=[0,2,4,8,10,12,14,18];
