    const l=lesson.learning,previousRhythm=JSON.parse(JSON.stringify(lesson.rhythm)),previousInstruction=JSON.parse(JSON.stringify({description:lesson.description,guide:lesson.guide,learning:l})),previousAssessmentFingerprint=Assessment.pianoSignature(lesson);
    const starts=[0,1,2,3,4,5,8,10,11,12,13,14,15,16,20,21,22,23,24,25,26,28,30],durations=[1,1,1,1,1,1,2,1,1,1,1,1,1,2,1,1,1,1,1,1,2,2,2],bpm=64;
    lesson.contentKind='exercise';lesson.rhythm=adapter.normalizeRhythm({version:1,source:'project-final-exam-eight-bars-v2',bpm,practiceBpm:bpm,timeSignature:{numerator:4,denominator:4},steps:starts.map((start,i)=>({startBeat:start,durationBeats:durations[i],restBeforeBeats:i?start-starts[i-1]-durations[i-1]:0,measure:Math.floor(start/4)+1,beatInMeasure:start%4,sourceStartMs:Math.round(start*60000/bpm),sourceDurationMs:Math.round(durations[i]*60000/bpm)}))},lesson.steps.length);
    lesson.description='Проверь знакомые навыки в восьми тактах 4/4: чередование рук, совместные пары, левый аккорд с правым ответом, правый аккорд и короткая учебная адаптация мелодии. Сохрани пульс при смене задания. Это контроль готового материала, а не новый самостоятельный навык.';
    lesson.guide=adapter.normalizeGuide({...lesson.guide,stage:'Контроль начального курса: подготовленные блоки',setup:'Сначала разбери подготовку по указанным ID. Левая находится над C3–E3, правая над C4–G4. Для левого трезвучия нужен G3. Педаль выключена; сначала играй с разбором, режим памяти выбирай отдельно.',motion:'Чередуй отдельные нажатия без удержания прежней руки. В совместных парах и аккордах все звуки начинают и заканчивают вместе. После левого аккорда правая отвечает по одной ноте: бас под ответом не удерживается. На паузе сохраняй счёт и готовь следующую задачу.',blind:'Игра без взгляда на руки остаётся практикой с экраном; для памяти нужен отдельный MIDI-режим. При потере позиции остановись и проверь клавиши. Во время контрольной попытки не ищи ответ в редакторе или образце.',mastery:'Проверь каждую часть отдельно, затем переходы между ними. Новая музыкальная версия требует новой попытки. MIDI подтверждает ноты, паузы и окончания в допусках проекта; пальцы, удобство руки и музыкальное качество оцениваются человеком. Чистая попытка не означает завершённое обучение инструменту.'});
    l.stage='p6';l.after='course10-07';l.requires=['course07-03','course08-07','course08-01','course04-04'];l.coverageDomain='coordination';l.articulation='standard';l.timingPrecision='beat-boundary-v2';l.goalCounting='checkpoint-only';l.goal=lesson.description;l.nextLessonId='course08-06';
    l.practiceSteps=[
      'Подготовка: совместные C3+C4, D3+D4, E3+E4 и чередование рук подготовлены в «Пары C–D–E одновременно»; левое трезвучие и правый ответ — в «Левый аккорд + правая мелодия»; правое трезвучие — в «C major правой: C–E–G»; четверти и половинные — в указанном ритмическом уроке. Здесь нет нового движения. Сначала послушай весь образец и назови момент каждой смены задачи. Узнаваемая концовка — учебная адаптация «Оды к радости», её известность не проверяет независимый слух.',
      'Медленный разбор по тактам. Такты 1–2: C3 левой 5, C4 правой 1, D3 левой 4, D4 правой 2, E3 левой 3, E4 правой 3 — шесть четвертей; затем две доли тишины. Такт 3: пары C3+C4 на две доли, D3+D4 и E3+E4 по доле; слева 5–4–3, справа 1–2–3. Такт 4: C3–E3–G3 левой 5–3–1 на долю, затем C4–D4–E4 правой 1–2–3 по доле. Такт 5: C4–E4–G4 правой 1–3–5 на две доли, затем две доли тишины. Считай «раз, два, три, четыре» и освобождай все звуки созвучия у его конца.',
      'Такты 6–8 правой: E4–E4–F4–G4 | G4–F4–E4 | D4–C4; пальцы 3–3–4–5 | 5–4–3 | 2–1. Первые шесть нот — четверти, последние E4, D4, C4 — половинные. Повторы E и G требуют нового нажатия. Это упрощённый ритм девяти начальных нот сопрано из «Оды к радости»: не точный ритм редакции. Конец C4 — после 32 долей. Блок около 3–5 минут: выбери одну трудную часть, затем свяжи её с соседней и только после этого сыграй целиком при учебных 64 BPM. Для памяти начни отдельную попытку без подсказок. После перерыва повтори; отдельно начни совместные пары с D, затем E, затем C, сохранив рисунок 2–1–1. Это самостоятельная проба переноса, не текущий зачёт и не новый урок.'
    ];
    l.selfCheck=['Чередование рук и левый аккорд с правым ответом остаются последовательными: прежний звук отпускается у вступления следующего.','В двух внутренних паузах по две доли нет нажатий или удержанных звуков. Счёт продолжается, новое вступление приходится на «раз».','Совместные пары и трезвучия имеют общий конец; одна рано снятая или задержанная клавиша меняет результат.','Знакомая мелодия сыграна с указанным учебным ритмом; её узнавание не подтверждает слух или освоение полного произведения.','Возвращайся к подготовке того компонента, который пока не получается. Контрольная запись не добавляет самостоятельную цель и не заменяет повтор после перерыва, перенос и помощь педагога. Следующее применение — подготовленный урок «Разложенные аккорды» для сопровождения.'];
    l.rhythmNotice='Учебная редакция проекта на 32 доли вместо прежних 30. Все 30 высот, руки, пальцы и 64 BPM сохранены. Первая пара начинается на 8-й доле вместо 7-й, правый аккорд — на 16-й вместо 17-й; внутренние паузы теперь по две доли. Финальные D4 и C4 удлинены до половинных и закрывают восьмой такт. Это явная адаптация, не реконструкция ритма произведения. Включён общий конец v2; прежние данные и результаты сохранены в истории.';
    l.references=[ODE_SCORE,ODE_CATALOG,SIMPLE_COUNTING,TIME_VALUES,PRACTICE];l.referenceTitles={[ODE_SCORE]:'Бетховен / Mutopia: с. 1, сопрано, такты 1–2 и первая нота такта 3',[ODE_CATALOG]:'Mutopia 528: Peter Chubb, редакция 2009 и Public Domain',[SIMPLE_COUNTING]:'Gotham, Hamm, Shaffer: четыре доли и счёт длинных звуков',[TIME_VALUES]:'The Open University: четверть и половинная',[PRACTICE]:'Bob Duke и Amy Simmons: посильная цель, короткий разбор и повтор'};l.sourceEvidenceIds=['mutopia-528-ode-2026-11-05','omt-simple-counting-2026-11-05','ou-time-values-2026-11-05','duke-simmons-small-goals-2026-11-05'];
    l.provenance={type:'study-or-adaptation',author:'Составной учебный этюд проекта; мелодическая концовка — Л. ван Бетховен',workTitle:'Ода к радости / Ode to Joy — девять начальных нот сопрано',sourceLocation:'Mutopia-2009/08/05-528, Peter Chubb, с. 1, сопрано: такты 1–2 и первая нота такта 3',sourceUrl:ODE_SCORE,sourceCatalogUrl:ODE_CATALOG,usage:'Наборщик и каталог заявляют Public Domain; остальные три голоса не используются.',adaptation:'Сопрано B4–B4–C5–D5–D5–C5–B4–A4–G4 перенесено вниз на семь полутонов в C major. Девять исходных четвертей превращены в шесть четвертей и три половинные E4–D4–C4, темп 100 заменён учебными 64 BPM; пальцы назначены проектом. Первые пять тактов — собственная техническая связка проекта.',purpose:'Проверить сохранение пульса при последовательном соединении уже подготовленных способов игры, не прибавляя контрольную попытку к самостоятельным новым навыкам.',context:'Именованные подготовки относятся к общим движениям, аккордам и длительностям; обязательного прохождения конкретного произведения нет. Полное заучивание музыки остаётся в «Произведениях».',sourceNote:'Концовка — Л. ван Бетховен, «Ода к радости / Ode to Joy». Проверенная редакция Peter Chubb, Mutopia-2009/08/05-528, с. 1: девять начальных нот сопрано, такты 1–2 и первая нота такта 3. Из G major они перенесены вниз на семь полутонов в C major; девять четвертей изменены на шесть четвертей и три половинные, 100 BPM — на учебные 64. Остальные голоса сняты, пальцы назначены проектом. Наборщик и каталог заявляют Public Domain. Первые пять тактов — собственная техническая связка проекта. Это учебная адаптация, не точные такты симфонии и не критическое издание. В каталоге источник Various; его дату c. 1800 как историческое свидетельство не используем. Open Music Theory и OpenLearn подтверждают счёт и отношения длительностей; Duke/Simmons — небольшие посильные задачи и возвращение к ним. Восьмитактовая связка, новый ритм, пальцы, 64 BPM и машинные допуски выбраны проектом, источники экзамен не утверждали.'};
    l.contentReview={id:'final-exam-eight-bar-checkpoint-v2',sourceFingerprint,previousAssessmentFingerprint,previousRhythm,previousInstruction,reviewedFingerprint:instructionFingerprint(lesson)};
    return 1;
