      l.rhythmNotice='Существующее техническое упражнение проекта: две пятёрки по одной доле, между ними одна доля тишины, исходный темп '+r.bpm+' BPM и 4/4 сохранены. Ноты, пальцы, временные данные и версия машинной оценки прежние. Пять нот фигуры не образуют полный пятидольный такт. Это не заимствованная музыкальная фраза.';
      l.references=[POSITION_CONTEXT,PRACTICE];l.referenceTitles={[POSITION_CONTEXT]:'Jerry Kovarsky: номера пальцев и подготовленная позиция',[PRACTICE]:'Duke и Simmons: небольшая цель, короткий разбор и возвращение после перерыва'};l.sourceEvidenceIds=['kovarsky-fingering-context-2026-11-05','duke-simmons-small-goals-2026-11-05'];
      l.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:'Подготовить три соседние высоты '+hand+' руки и возврат через средний палец; отделить повтор опорного до тишиной.',context:'Короткие соседние мотивы и чтение трёх подготовленных высот. В левой руке номера по высоте идут в обратном порядке; чтение ноты не назначает руку автоматически.',sourceNote:'Последовательность и числовые параметры заданы проектом. Kovarsky подтверждает нумерацию 1–5 и планирование позиции, Duke и Simmons — конкретную небольшую цель, разбор короткого участка и распределённую практику. Эти авторы не утверждали нашу аппликатуру каждой фразы, MIDI-допуски или весь курс. Исторической атрибуции упражнению нет.'};
