      const lesson=lessons.find(l=>l.id===r.id),learning=lesson?.learning;
      if(!learning||lesson.contentKind==='piece'||lesson.exam!==false||learning.contentReview||instructionFingerprint(lesson)!==r.fingerprint)continue;
      const previousInstruction=JSON.parse(JSON.stringify({description:lesson.description,guide:lesson.guide,learning})),previousAssessmentFingerprint=Assessment.pianoSignature(lesson);
      const goal='Найди '+r.note+' и сыграй '+(r.hand==='right'?'правым большим 1':'левым мизинцем 5')+': четыре четверти, долю тишины и ещё четыре четверти. Каждое повторение — новое нажатие той же клавиши; после тишины вступи на «два».';
