  function reviewRightFiveFingerPreparation(lessons,adapter){
    let changed=0;
    for(const r of rightFiveFingerReviews){
      const lesson=lessons.find(l=>l.id===r.id),learning=lesson?.learning;
      if(!learning||lesson.contentKind==='piece'||(learning.contentReview?.id||null)!==(r.previousReview||null)||instructionFingerprint(lesson)!==r.fingerprint)continue;
      const previousInstruction=JSON.parse(JSON.stringify({description:lesson.description,guide:lesson.guide,learning})),previousAssessmentFingerprint=Assessment.pianoSignature(lesson);
      if(r.linkOnly){
        learning.nextLessonId=r.next;
        learning.practiceSteps=[...learning.practiceSteps,'Следующий шаг — detail-p-right-upper-position-01: отдельно подготовь E4–F4–G4 пальцами 3–4–5, затем соединяй всю позицию в course02-03. Существующие legato-пары требуют пятипальцевой подготовки и не заменяют этот ранний мостик.'];
      }else{
        lesson.description='Дважды сыграй '+r.notes+' правой рукой '+r.digits+'. Между фразами оставь одну тихую долю. Соедини уже подготовленные части одной позиции C4–G4; это пять высот, не полная гамма.';
        lesson.guide=adapter.normalizeGuide({stage:'Правая: соединить пять подготовленных пальцев',setup:'Сначала закончи отдельную подготовку 3–4–5. Проверь C4–G4: 1=C4, 2=D4, 3=E4, 4=F4, 5=G4. Левая отдыхает, педаль выключена.',motion:r.purpose+' '+r.turn+' Сохраняй удобную кисть без высокого подъёма пальцев и без лишних нажатий.',blind:'Сначала представь направление и назови начальный звук. Разбери с подсказками, а память проверь отдельно после перерыва; знакомый рисунок не является независимым тестом слуха.',mastery:'Ноты, равные доли, отпускания и тишина совпадают в обеих фразах. MIDI проверяет ноты и время, а пальцы и удобство движения — отдельная самопроверка. Повтори после перерыва, затем из памяти на следующий день.'});
        Object.assign(learning,{stage:'p2',after:r.requires[0],requires:[...r.requires],coverageDomain:'fingers',goal:lesson.description,nextLessonId:r.next,
          practiceSteps:[
            'Подготовка: сыграй отдельно C4–D4–E4 и E4–F4–G4 подготовленными пальцами. Теперь соедини '+r.notes+' пальцами '+r.digits+'. Начало '+r.first+' найди заранее; не подменяй мизинец другим пальцем. Обычный профиль звучания сохранён, отдельного legato/staccato здесь нет.',
            'Медленно сыграй одну пятёрку и остановись. В исходнике 60 BPM, все звуки по одной доле. Вступления 0, 1, 2, 3, 4; затем 6, 7, 8, 9, 10 долей. Первая '+r.last+' заканчивается у 5, вторая фраза начинается у 6: нужна полная доля тишины. Последнее звучание заканчивается у 11. Счёт 4/4 продолжается; пятёрка нот не является пятидольным тактом.',
            'Послушай образец и пропой направление в удобной октаве. '+r.turn+' Не сокращай последнюю ноту и не играй соседнюю чёрную F♯4. Если переход неудобен, вернись к короткой паре без давления, затем снова соединяй фразу.',
            'Блок около 3–5 минут: короткие пробы с остановками и отдыхом. Вне MIDI-зачёта заранее разбери '+r.transfer+' по одной доле и сыграй без подсказки. Это открытая проба применения, не неизвестный слуховой/нотный тест и не дополнительный урок. Вернись после перерыва и на следующий день.'
          ],
          selfCheck:['Правая '+r.notes+', пальцы '+r.digits+'. MIDI пальцы не распознаёт.','Все пять звуков находятся в C4–G4; нет подкладывания, смены руки, педали или лишних нот.','На стыке двух фраз одна доля тишины, новое начало заранее подготовлено.','Конец фразы не ускоряется; кисть удобна, мизинец не поджат. При напряжении остановись.','Проба переноса и поздний повтор оцениваются отдельно от немедленного исполнения знакомого рисунка.'],
          rhythmNotice:'Две пятипальцевые фразы по пять четвертей с одной долей тишины между ними, 60 BPM и 4/4. Исходные ноты, пальцы, длительности, паузы и профиль артикуляции сохранены; музыкальная версия не меняется.'});
        rightPositionReferences(learning,r.purpose);
      }
      learning.contentReview={id:'right-five-finger-preparation-v1',sourceFingerprint:r.fingerprint,previousAssessmentFingerprint,previousInstruction,reviewedFingerprint:instructionFingerprint(lesson)};
      changed++;
    }
    return changed;
  }
